begin;
select plan(8);
insert into agencies(id,name,code) values('16000000-0000-0000-0000-000000000001','Draft preservation','DRAFT-PRESERVE');
insert into portal_profiles(id,auth_user_id,email) values('26000000-0000-0000-0000-000000000001','36000000-0000-0000-0000-000000000001','draft-preserve@example.test');
insert into agency_memberships(user_id,agency_id) values('26000000-0000-0000-0000-000000000001','16000000-0000-0000-0000-000000000001');
insert into enrollment_applications(id,agency_id,assigned_agent_id,data) values('46000000-0000-0000-0000-000000000001','16000000-0000-0000-0000-000000000001','26000000-0000-0000-0000-000000000001','{"wizard":{"confirmed":["first_name"]},"provenance":{"first_name":"Reviewed passport"}}');
select has_function('public','portal_save_application_draft',array['uuid','jsonb','text','text','text','integer'],'atomic draft command exists');
set local role authenticated;
set local request.jwt.claim.sub='36000000-0000-0000-0000-000000000001';
select lives_ok($$select portal_save_application_draft('46000000-0000-0000-0000-000000000001','{"values":{"first_name":"Reviewed"}}','Reviewed','student@example.test','2027',20)$$,'own draft saves');
select is((select data->'wizard'->'confirmed' from enrollment_applications where id='46000000-0000-0000-0000-000000000001'),'["first_name"]'::jsonb,'confirmed wizard metadata preserved');
select is((select data->'values'->>'first_name' from enrollment_applications where id='46000000-0000-0000-0000-000000000001'),'Reviewed','edited form value saved');
select throws_ok($$select portal_save_application_draft('46000000-0000-0000-0000-000000000001','{"wizard":{}}','','','',0)$$,'22023',null,'draft command cannot replace review metadata');
set local request.jwt.claim.sub='36000000-0000-0000-0000-000000000002';
select throws_ok($$select portal_save_application_draft('46000000-0000-0000-0000-000000000001','{}','','','',0)$$,'42501',null,'foreign actor denied');
reset role;
update enrollment_applications set status='submitted' where id='46000000-0000-0000-0000-000000000001';
set local role authenticated;
set local request.jwt.claim.sub='36000000-0000-0000-0000-000000000001';
select throws_ok($$select portal_save_application_draft('46000000-0000-0000-0000-000000000001','{}','','','',0)$$,'42501',null,'submitted draft save denied');
select throws_ok($$select portal_save_application_draft('46000000-0000-0000-0000-000000000099','{}','','','',0)$$,'42501',null,'missing application denied');
select * from finish();
rollback;
